 final JTable accountTable=new JTable(accountModel),inputTable=new JTable(inputModel),taskTable=new JTable(taskModel),detailTable=new JTable(detailModel);final JLabel accountSummary=new JLabel(),taskSummary=new JLabel();
 List<AssessmentTracker.OperationView> operations=List.of(),taskDetails=List.of();List<AssessmentTracker.TaskView> tasks=List.of();boolean refreshing;
