  accountsPage.add(TargetWindow.options(row(new JLabel("점검 계정"),accountChoice,accountFilter,button("계정 등록",this::openAccount),button("계정 이름/역할",this::editAccount),button("선택 트래픽 연결",this::bindSelected),button("세션 연결 해제",()->{tracker.unbind(selectedAccount());refresh();})),row(button("선택 URL 완료",()->finish(true)),button("완료 해제",()->finish(false)),button("입력 완료 / 해제",this::finishInput),button("선택 API → 업무",this::openTarget),button("점검 이력",this::openHistory))),BorderLayout.NORTH);
